"""
Authentic workbooks embedded as base85-encoded lzma archives, one constant per file. The samples
originate from the test suites of the `xlrd2` and `pyxlsb2` projects, which distribute them under
the Apache License 2.0; they are produced by a range of authors (Microsoft Excel, LibreOffice,
Apache POI) and collectively cover rich text, shared strings, inline strings, formula results,
date styles, error values, control characters, nonstandard part naming, the BIFF record format
from the worksheet-only BIFF4 stream to BIFF8, a workbook whose OLE container is defective, a
sheet that contains nothing but a picture, and the MS-XLSB record format with both date epochs.
"""
import base64
import lzma


def _embedded(literal: str) -> bytes:
    return lzma.decompress(base64.b85decode(literal))


